{
	FAR struct sunxi_gpadc_lowerhalf_s *priv = (FAR struct sunxi_gpadc_lowerhalf_s *)dev->ad_priv;
	DEBUGASSERT(priv);

	priv->cb = callback;

	return OK;
}

