+static int qiban_clamp_int(int value, int minimum, int maximum)
+{
+  if (value < minimum)
+    {
+      return minimum;
+    }
+
+  if (value > maximum)
+    {
+      return maximum;
+    }
+
+  return value;
+}
+
+static int qiban_read_adc_sample(FAR const char *path, FAR int *out_value)
+{
+  struct adc_msg_s sample;
+  int fd;
+  ssize_t nbytes;
+  int ret;
+
+  fd = open(path, O_RDONLY);
+  if (fd < 0)
+    {
+      return -errno;
+    }
+
+  ret = ioctl(fd, ANIOC_TRIGGER, 0);
+  if (ret < 0)
+    {
+      ret = -errno;
+      close(fd);
+      return ret;
+    }
+
+  nbytes = read(fd, &sample, sizeof(sample));
+  if (nbytes < 0)
+    {
+      ret = -errno;
+      close(fd);
+      return ret;
+    }
+
+  close(fd);
+
+  if (nbytes != sizeof(sample))
+    {
+      return -EIO;
+    }
+
+  *out_value = sample.am_data;
+  return OK;
+}
+
+static void qiban_apply_gpadc_battery(FAR struct qiban_vehicle_state_s *state)
